#include <stdio.h>
int main(void)  {
    // 行列可很大，只计算数量；使用 64 位整数，不创建二维灯板。
    long long rows, columns;
    scanf("%lld%lld", &rows, &columns);
    long long answer;
    // 单行或单列的四条边重合，必须直接返回全部格子数量。
    if (rows == 1 || columns == 1)  {
        answer = rows * columns;
    }
    else  {
        answer = 2 * rows + 2 * columns - 4;
    }
    // 普通矩形四个角各多算一次，修正后的 answer 才是独立灯数。
    printf("%lld\n", answer);
    return 0;
}

